package com.bank.consolidated.service;

import com.bank.consolidated.dto.ConsolidatedStatement;
import com.bank.consolidated.model.Transaction;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Stream;

@Service
@Slf4j
public class ConsolidatedStatementService {

    // Simulated data sources — some return null for customers without that product
    private List<Transaction> getCoreTransactions(String customerId) {
        return List.of(
            new Transaction("BANK-001", "CORE", "Salary Credit", new BigDecimal("85000"), null),
            new Transaction("BANK-002", "CORE", "Rent Debit", new BigDecimal("25000"), "Monthly rent")
        );
    }

    // Returns null for customers without credit card
    private List<Transaction> getCreditCardTransactions(String customerId) {
        if ("SAV2001".equals(customerId)) {
            return List.of(
                new Transaction("CARD-001", "CREDIT_CARD", "Amazon", new BigDecimal("3500"), null),
                new Transaction("CARD-002", "CREDIT_CARD", "Fuel", new BigDecimal("2200"), "Petrol pump")
            );
        }
        return null;  // customer has no credit card!
    }

    // Returns null for non-investors
    private List<Transaction> getInvestmentTransactions(String customerId) {
        if ("SAV2001".equals(customerId)) {
            return List.of(
                new Transaction("INV-001", "INVESTMENT", "SIP HDFC MF", new BigDecimal("10000"), "Monthly SIP")
            );
        }
        return null;  // customer has no investments!
    }

    public ConsolidatedStatement buildStatement(String customerId) {

        List<Transaction> core = getCoreTransactions(customerId);
        List<Transaction> cards = getCreditCardTransactions(customerId);
        List<Transaction> investments = getInvestmentTransactions(customerId);

        // ═══ Stream.ofNullable: safely handle nullable sources ═══
        // cards might be null (no credit card). investments might be null (non-investor).
        // ofNullable(null) → Stream.empty(). ofNullable(list) → Stream.of(list).

        // ═══ Stream.concat: merge two streams ═══
        Stream<Transaction> coreStream = core.stream();
        Stream<Transaction> cardStream = Stream.ofNullable(cards).flatMap(Collection::stream);
        Stream<Transaction> investStream = Stream.ofNullable(investments).flatMap(Collection::stream);

        // ═══ Merge all three sources using concat chain ═══
        List<Transaction> allTxns = Stream.of(coreStream, cardStream, investStream)
            .flatMap(s -> s)  // Stream<Stream<Txn>> → Stream<Txn>
            .toList();

        log.info("Consolidated {} transactions from {} sources for {}",
            allTxns.size(), countNonNullSources(core, cards, investments), customerId);

        // ═══ ofNullable inside flatMap: extract non-null notes ═══
        List<String> nonNullNotes = allTxns.stream()
            .flatMap(t -> Stream.ofNullable(t.note()))  // null notes → empty stream → skipped
            .toList();
        log.info("Non-null notes: {}", nonNullNotes);

        BigDecimal total = allTxns.stream()
            .map(Transaction::amount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        List<String> display = allTxns.stream()
            .map(t -> t.txnId() + " [" + t.source() + "] " + t.description() + " Rs." + t.amount())
            .toList();

        return new ConsolidatedStatement(customerId, allTxns.size(), total,
            display, nonNullNotes,
            "ofNullable(nullableList).flatMap(Collection::stream) + Stream.of(s1,s2,s3).flatMap(s->s)");
    }

    private int countNonNullSources(Object... sources) {
        return (int) Stream.of(sources).filter(Objects::nonNull).count();
    }
}
```

