// ─── File: src/test/java/com/bank/consolidated/service/OfNullableConcatTest.java ───
package com.bank.consolidated.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class OfNullableConcatTest {

    @Test
    void ofNullableWithNonNull() {
        List<String> result = Stream.ofNullable("RELIANCE").toList();
        assertThat(result).containsExactly("RELIANCE");
    }

    @Test
    void ofNullableWithNull() {
        List<String> result = Stream.ofNullable(null).toList();
        assertThat(result).isEmpty();  // empty stream, not NPE!
    }

    @Test
    void ofNullableInFlatMapForNullableFields() {
        record Trade(String id, String note) {}
        var trades = List.of(
            new Trade("T1", "risk note"), new Trade("T2", null), new Trade("T3", "audit note"));

        List<String> notes = trades.stream()
            .flatMap(t -> Stream.ofNullable(t.note()))
            .toList();
        assertThat(notes).containsExactly("risk note", "audit note");  // null skipped!
    }

    @Test
    void ofNullableForNullableList() {
        List<String> nullList = null;
        List<String> presentList = List.of("A", "B");

        List<String> fromNull = Stream.ofNullable(nullList)
            .flatMap(Collection::stream).toList();
        List<String> fromPresent = Stream.ofNullable(presentList)
            .flatMap(Collection::stream).toList();

        assertThat(fromNull).isEmpty();
        assertThat(fromPresent).containsExactly("A", "B");
    }

    @Test
    void concatMergesTwoStreams() {
        List<String> merged = Stream.concat(
            Stream.of("A", "B"),
            Stream.of("C", "D")
        ).toList();
        assertThat(merged).containsExactly("A", "B", "C", "D");
    }

    @Test
    void concatIsLazy() {
        var counter = new java.util.concurrent.atomic.AtomicInteger(0);
        Stream<String> s1 = Stream.of("A").peek(s -> counter.incrementAndGet());
        Stream<String> s2 = Stream.of("B").peek(s -> counter.incrementAndGet());
        Stream<String> concatenated = Stream.concat(s1, s2);

        assertThat(counter.get()).isZero();  // LAZY — nothing processed yet!
        concatenated.toList();
        assertThat(counter.get()).isEqualTo(2);  // now both processed
    }

    @Test
    void mergeMultipleStreamsWithFlatMap() {
        List<String> merged = Stream.of(
            Stream.of("A", "B"),
            Stream.of("C"),
            Stream.of("D", "E")
        ).flatMap(s -> s).toList();
        assertThat(merged).containsExactly("A", "B", "C", "D", "E");
    }

    @Test
    void beforeJava9VerboseNullCheck() {
        String value = null;

        // Before Java 9:
        Stream<String> verbose = value != null ? Stream.of(value) : Stream.empty();
        assertThat(verbose.toList()).isEmpty();

        // After Java 9:
        Stream<String> clean = Stream.ofNullable(value);
        assertThat(clean.toList()).isEmpty();
        // Same result, cleaner code!
    }
}
